                                                                                                function mostrarLogo() {
                                                                                                    basic.clearScreen()

                                                                                                        for (brilho = 10; brilho <= 255; brilho += 5) {
                                                                                                                led.plotBrightness(2, 0, brilho)
                                                                                                                        led.plotBrightness(2, 1, brilho)
                                                                                                                                led.plotBrightness(2, 2, brilho)

                                                                                                                                        led.plotBrightness(0, 3, brilho)
                                                                                                                                                led.plotBrightness(1, 3, brilho)
                                                                                                                                                        led.plotBrightness(2, 3, brilho)
                                                                                                                                                                led.plotBrightness(3, 3, brilho)
                                                                                                                                                                        led.plotBrightness(4, 3, brilho)

                                                                                                                                                                                led.plotBrightness(0, 4, brilho)
                                                                                                                                                                                        led.plotBrightness(1, 4, brilho)
                                                                                                                                                                                                led.plotBrightness(3, 4, brilho)
                                                                                                                                                                                                        led.plotBrightness(4, 4, brilho)

                                                                                                                                                                                                                basic.pause(30)
                                                                                                                                                                                                                    }

                                                                                                                                                                                                                        basic.pause(1000)

                                                                                                                                                                                                                            for (brilho = 255; brilho >= 0; brilho -= 5) {
                                                                                                                                                                                                                                    led.plotBrightness(2, 0, brilho)
                                                                                                                                                                                                                                            led.plotBrightness(2, 1, brilho)
                                                                                                                                                                                                                                                    led.plotBrightness(2, 2, brilho)

                                                                                                                                                                                                                                                            led.plotBrightness(0, 3, brilho)
                                                                                                                                                                                                                                                                    led.plotBrightness(1, 3, brilho)
                                                                                                                                                                                                                                                                            led.plotBrightness(2, 3, brilho)
                                                                                                                                                                                                                                                                                    led.plotBrightness(3, 3, brilho)
                                                                                                                                                                                                                                                                                            led.plotBrightness(4, 3, brilho)

                                                                                                                                                                                                                                                                                                    led.plotBrightness(0, 4, brilho)
                                                                                                                                                                                                                                                                                                            led.plotBrightness(1, 4, brilho)
                                                                                                                                                                                                                                                                                                                    led.plotBrightness(3, 4, brilho)
                                                                                                                                                                                                                                                                                                                            led.plotBrightness(4, 4, brilho)

                                                                                                                                                                                                                                                                                                                                    basic.pause(30)
                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                            basic.clearScreen()
                                                                                                                                                                                                                                                                                                                                            }

